CREATE TABLE IF NOT EXISTS pilot_meta (id int PRIMARY KEY CHECK(id=1), schema_version int NOT NULL, marker text NOT NULL CHECK(marker='FLSD_ISOLATED_PILOT_ONLY'));
INSERT INTO pilot_meta VALUES(1,1,'FLSD_ISOLATED_PILOT_ONLY') ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS pilot_users(id uuid PRIMARY KEY,email text NOT NULL UNIQUE,name text NOT NULL,password_hash text NOT NULL,role text NOT NULL CHECK(role IN ('OWNER','ADMIN','BILLING','OPERATIONS','VIEWER')),active boolean NOT NULL DEFAULT true,version int NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS pilot_sessions(token_hash text PRIMARY KEY,user_id uuid NOT NULL REFERENCES pilot_users(id),expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS pilot_session_expiry ON pilot_sessions(expires_at);
CREATE TABLE IF NOT EXISTS pilot_login_attempts(key text PRIMARY KEY,failures int NOT NULL DEFAULT 0,window_start timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS pilot_workspace(id int PRIMARY KEY CHECK(id=1),revision int NOT NULL DEFAULT 0,state jsonb NOT NULL,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS pilot_operations(id uuid PRIMARY KEY,actor_id uuid NOT NULL REFERENCES pilot_users(id),digest char(64) NOT NULL,revision int NOT NULL,result jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS pilot_audit(id uuid PRIMARY KEY,actor_id uuid NOT NULL REFERENCES pilot_users(id),operation_id uuid REFERENCES pilot_operations(id),action text NOT NULL,entity_id text NOT NULL,detail jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS pilot_customers(id text PRIMARY KEY,archived boolean NOT NULL DEFAULT false,name text NOT NULL,tin text,address text,active boolean NOT NULL,payload jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS pilot_trips(id text PRIMARY KEY,archived boolean NOT NULL DEFAULT false,customer_id text NOT NULL REFERENCES pilot_customers(id),amount numeric(18,2) NOT NULL CHECK(amount>0),workflow text NOT NULL CHECK(workflow IN ('DIRECT','CORPORATE')),service_date date NOT NULL,payload jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS pilot_documents(id text PRIMARY KEY,customer_id text NOT NULL REFERENCES pilot_customers(id),amount numeric(18,2) NOT NULL CHECK(amount>=0),document_type text NOT NULL,payload jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS pilot_receipts(id text PRIMARY KEY,trip_id text NOT NULL REFERENCES pilot_trips(id),customer_id text NOT NULL REFERENCES pilot_customers(id),amount numeric(18,2) NOT NULL CHECK(amount>0),state text NOT NULL,payload jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS pilot_allocations(id text PRIMARY KEY,receipt_id text NOT NULL REFERENCES pilot_receipts(id),trip_id text NOT NULL REFERENCES pilot_trips(id),amount numeric(18,2) NOT NULL CHECK(amount>0),reversed numeric(18,2) NOT NULL CHECK(reversed>=0 AND reversed<=amount),payload jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS pilot_refunds(id text PRIMARY KEY,receipt_id text NOT NULL REFERENCES pilot_receipts(id),amount numeric(18,2) NOT NULL CHECK(amount>0),state text NOT NULL,payload jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS pilot_remittances(id text PRIMARY KEY,receipt_id text NOT NULL REFERENCES pilot_receipts(id),tendered numeric(18,2) NOT NULL CHECK(tendered>0),accepted numeric(18,2) NOT NULL CHECK(accepted>=0 AND accepted<=tendered),payload jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS pilot_attachments(id text PRIMARY KEY,invoice_id text NOT NULL REFERENCES pilot_documents(id),name text NOT NULL,mime_type text NOT NULL,content bytea NOT NULL);
